function gradCircle(x, y, r, cc, c2, c3){
	let splice= TAU/200
	noStroke()
	fill(0)
	for(let a=0; a<TAU; a+=splice){

		let mixer= map(sin(a), -1, 1, 0, 1)
		//let outerC= lerpColor(c2, c3, mixer)
		let outerC= color(spectral.mix(c2, c3, mixer))

		coloring= drawingContext.createRadialGradient(x, y, 0.0, x+ random(-r/50, r/50),y, r*0.75)
		coloring.addColorStop(0, cc)
		coloring.addColorStop(1, outerC)
		drawingContext.fillStyle= coloring	

		arc(x, y, r*2, r*2, a, a+splice+splice/30)

	}

}

